import { LoginPage } from './pages/LoginPage'
import { RegisterPage } from './pages/RegisterPage'

type Screen = 'welcome' | 'login' | 'register'

function App() {
  const [language, setLanguage] = useState<Language>('es')
  const [screen, setScreen] = useState<Screen>('welcome')

  const text = useMemo(() => translations[language], [language])

  const navigateTo = (nextScreen: Screen) => setScreen(nextScreen)

  return (
    <div className="app-shell">
      <Header
        language={language}
        onLanguageChange={setLanguage}
        onNavigate={navigateTo}
      />

      {screen === 'welcome' && (
        <main className="welcome-page">
          <section className="hero-panel">
            <p className="eyebrow">{text.tagline}</p>
            <h1>{text.welcomeTitle}</h1>
            <p className="subtitle">{text.welcomeSubtitle}</p>

            <div className="cta-row">
              <button type="button" className="primary-button" onClick={() => navigateTo('login')}>
                {text.login}
              </button>
              <button type="button" className="secondary-button" onClick={() => navigateTo('register')}>
                {text.register}
              </button>
            </div>
          </section>
        </main>
      )}

      {screen === 'login' && <LoginPage language={language} onNavigate={navigateTo} />}
      {screen === 'register' && <RegisterPage language={language} onNavigate={navigateTo} />}

  onNavigate: (screen: 'welcome' | 'login' | 'register') => void
}

export function Header({ language, onLanguageChange, onNavigate }: HeaderProps) {
  const text = translations[language]

  return (
    <header className="topbar">
      <button type="button" className="brand-block brand-button" onClick={() => onNavigate('welcome')}>
        <span className="brand-mark">A</span>
        <span className="brand-name">{text.brand}</span>
      </button>

      <div className="header-actions">
        <label className="language-selector" htmlFor="language-select">
          <span>{text.language}</span>
          <select
            id="language-select"
            value={language}
            onChange={(event) => onLanguageChange(event.target.value as Language)}
            aria-label={text.language}
          >
            {languages.map((item) => (
              <option key={item.code} value={item.code}>
                {item.label}
              </option>
            ))}
          </select>
        </label>

        <button type="button" className="nav-link" onClick={() => onNavigate('login')}>
          {text.login}
        </button>
        <button type="button" className="nav-link primary" onClick={() => onNavigate('register')}>
          {text.register}
        </button

