type ModuleViewPageProps = {
  language: Language
}

export function ModuleViewPage({ language }: ModuleViewPageProps) {
  const { viewKey } = useParams()
  const currentPath = viewKey ? `/dashboard/${viewKey}` : '/dashboard'
